#include <bits/stdc++.h>
using namespace std;

const int MAX_T = 5000;
const int MAX_N = 2e5;

vector<int> a;
vector<int> sorted_a;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        a.clear();
        for (int i = 0; i < n; ++i) {
            int x;
            cin >> x;
            a.push_back(x);
        }

        // Sort the array in descending order
        sort(a.begin(), a.end(), greater<int>());
        sorted_a = a;

        // Calculate the initial outcome
        int sum_A = 0, sum_B = 0;
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) {
                sum_A += sorted_a[i];
            } else {
                sum_B += sorted_a[i];
            }
        }

        int max_possible = k;
        int delta = 0;

        // Allocate as much as possible to Bob's elements
        for (int i = 0; i < n; ++i) {
            if (max_possible <= 0) break;
            if (i % 2 == 1) { // Bob's element
                delta += max_possible;
                max_possible -= max_possible;
            }
        }

        // The new outcome is sum_A - (sum_B + delta)
        cout << (sum_A - (sum_B + delta)) << "\n";
    }

    return 0;
}
